-- The two checklists published on 2026-10-28: When Your Teenager Will Not
-- Talk to You (Teenagers) and Putting Down the Cigarettes (Smoking).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-28`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-your-teenager-will-not-talk-to-you', 'When Your Teenager Will Not Talk to You', 'For a stretch when a teenager has gone quiet and every question makes it worse. It trades the interview for one ordinary comment a day, moves the talking sideways into a car or a walk, and keeps your first reaction off your face.', 'Teenagers', '["Say one ordinary thing a day with no question in it — a comment is easier to answer than an interview.", "Take the conversation sideways — a car, a walk or the dishes beats sitting face to face.", "Ask about the thing, not the feeling — their game or their friend opens the door wider.", "Let the silence last longer than is comfortable — most of what you want comes after the pause.", "Keep the first reaction off your face — one wince teaches them what not to bring you.", "Separate the rule from the relationship — a curfew can hold while the warmth stays.", "Say what you are not going to do about it — not telling anyone buys more than a promise.", "Make sure one other adult is around — an aunt, a coach or a teacher counts as reachable.", "Say the door is open and then stop saying it — repeating it turns it into pressure."]'::jsonb, 'as needed', array['Parenting', 'Communication']::text[], 1, '2026-10-28T16:00:00+00:00'::timestamptz),
  ('putting-down-the-cigarettes', 'Putting Down the Cigarettes', 'For the week you decide to stop smoking. It sets a date with witnesses, gets real help from a pharmacist, plans the three hardest cigarettes of the day, clears what is within reach, and treats one lapse as one cigarette rather than a return.', 'Smoking', '["Pick the date and tell two people — a date with witnesses is a different kind of plan.", "Ask the pharmacist what to use — patches and gum beat willpower on its own.", "Name the three hardest cigarettes of your day — those are the ones to plan for first.", "Clear the car, the lighters and the ashtray — the first week is decided by what is in reach.", "Decide what your hands will do instead — a toothpick, a pen, a walk to the end of the block.", "Change the route that goes past the store — a habit lives in a place as much as a craving.", "Put the money somewhere you can see it — a jar on the counter argues better than arithmetic.", "Treat one cigarette as one cigarette — a lapse is not the start of smoking again.", "Call 1-800-QUIT-NOW when it gets loud — the free coaching line is there for exactly this."]'::jsonb, 'as needed', array['Habits', 'Resilience']::text[], 1, '2026-10-28T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
